    - {round: 12, action: "Add SFT-injected qualifier at first occurrence of contamination in each section", assigned_to: "paper_agent", status: "in_progress"}

- id: "R3-W10"
  summary: "Additive linear γ assumption untested"
  category: method
  severity: critical
