  resolution_round: 7

- id: "R4-N1"
  summary: "Domain-level γ significance — P(γ<0) inconsistency and Bonferroni claim unstable"
  category: method
  severity: critical
  status: open
  first_raised_round: 4
  last_seen_round: 12
  mentions:
    - {round: 4, reviewers: "R1,R2", note: "Bonferroni α=0.00625; CI upper bound likely includes zero."}
    - {round: 5, reviewers: "R1,R2", note: "Social Sciences at 99.1% does not pass Bonferroni."}
    - {round: 6, reviewers: "R1,R2", note: "J=16 data available but main text still presents J=13."}
    - {round: 10, reviewers: "R1,R2", note: "CONSENSUS Must-Fix. P(γ<0) inconsistency between §5.7 and Appendix K."}
    - {round: 12, reviewers: "R1", note: "Minor-5: Abstract cites 99.7% without mentioning tight prior failure."}
  action_items:
    - {round: 4, action: "Report Bonferroni corrected results", assigned_to: "paper_agent", status: "done"}
    - {round: 6, action: "Switch main text to J=16 results", assigned_to: "paper_agent", status: "done"}
    - {round: 10, action: "Resolve P(γ<0) numerical inconsistency; mark γ conclusions exploratory", assigned_to: "paper_agent", status: "open"}

- id: "R3-N3"
  summary: "ARC PPP < 0.05 across all J — IRT results unreliable"
  category: method
  severity: warning
  status: in_progress
  first_raised_round: 3
  last_seen_round: 12
  mentions:
    - {round: 3, reviewers: "R1", note: "Within-family J=13 ARC PPP=0.003 not reported."}
    - {round: 5, reviewers: "R1,R2", note: "Table 3 now has PPP=0.003. Move ARC IRT to Appendix."}
    - {round: 10, reviewers: "R1,R2", note: "MMLU PPP=0.16-0.25 only in Appendix, not main text."}
    - {round: 12, reviewers: "R1,R2", note: "Cross-benchmark direction based on raw accuracy not IRT. Paper should explicitly separate raw-accuracy and IRT-based conclusions."}
  action_items:
    - {round: 9, action: "Add ARC PPP=0.003 discussion in main text", assigned_to: "paper_agent", status: "done"}
    - {round: 10, action: "Report MMLU PPP in main text", assigned_to: "paper_agent", status: "open"}
    - {round: 12, action: "Add explicit statement in §5.2 that cross-benchmark direction conclusions are based on raw accuracy, not IRT estimates", assigned_to: "paper_agent", status: "in_progress"}

